/**
 *
 * useForm is a composable that provides form state management and validation.
 *
 * [Live Demo](https://www.primevue.dev/forms/)
 *
 * @module useform
 *
 */

/**
 * The reactive state of a form field.
 */
export interface useFormFieldState {
    /**
     * The value of the form field.
     */
    value: any;
    /**
     * Whether the form field has been touched.
     * @defaultValue false
     */
    touched: boolean;
    /**
     * Whether the form field has been modified.
     * @defaultValue false
     */
    dirty: boolean;
    /**
     * Whether the form field has not been modified.
     * @defaultValue true
     */
    pristine: boolean;
    /**
     * Whether the form field is valid.
     * @defaultValue true
     */
    valid: boolean;
    /**
     * Whether the form field is invalid.
     * @defaultValue false
     */
    invalid: boolean;
    /**
     * The first error message of the form field.
     */
    error: any;
    /**
     * All error messages of the form field.
     * @defaultValue []
     */
    errors: any[];
}

/**
 * Configuration options for a form field registered via `defineField`.
 */
export interface useFormFieldOptions {
    /**
     * The initial value of the form field.
     */
    initialValue?: any;
    /**
     * Additional props to bind to the form field, either as a static object or a function of the current field state.
     */
    props?: Record<string, any> | ((state: useFormFieldState) => Record<string, any>);
    /**
     * Whether to validate the form field when it loses focus (on blur).
     * @defaultValue false
     */
    validateOnBlur?: boolean;
    /**
     * Whether to validate the form field when its value changes.
     * @defaultValue true
     */
    validateOnValueUpdate?: boolean;
    /**
     * A function that resolves validation logic for this specific field.
     * @param {Object} options - Field resolver options.
     */
    resolver?: (options: { values: any; value: any; name: string }) => Promise<Record<string, any>> | Record<string, any> | undefined;
    /**
     * Callback invoked when the form field loses focus (on blur).
     * @param {Event} event - Browser event.
     */
    onBlur?: (event: Event) => void;
    /**
     * Callback invoked when the form field value is input.
     * @param {Event | any} event - Browser event or a custom event carrying a `value` property.
     */
    onInput?: (event: Event | any) => void;
    /**
     * Callback invoked when the form field value changes.
     * @param {Event | any} event - Browser event or a custom event carrying a `value` property.
     */
    onChange?: (event: Event | any) => void;
    /**
     * Callback invoked when the form field is reported as invalid.
     * @param {any[]} errors - The error messages for the field.
     */
    onInvalid?: (errors: any[]) => void;
    [key: string]: any;
}

/**
 * The bindable props of a registered form field, to be spread onto the underlying input.
 */
export interface useFormFieldProps {
    /**
     * The name of the form field.
     */
    name: string;
    /**
     * Callback invoked when the form field loses focus (on blur).
     * @param {Event} event - Browser event.
     */
    onBlur: (event: Event) => void;
    /**
     * Callback invoked when the form field value is input.
     * @param {Event | any} event - Browser event or a custom event carrying a `value` property.
     */
    onInput: (event: Event | any) => void;
    /**
     * Callback invoked when the form field value changes.
     * @param {Event | any} event - Browser event or a custom event carrying a `value` property.
     */
    onChange: (event: Event | any) => void;
    /**
     * Callback invoked when the form field is reported as invalid.
     * @param {any[]} errors - The error messages for the field.
     */
    onInvalid: (errors: any[]) => void;
    [key: string]: any;
}

/**
 * A registered form field, keeping its bindable props, live state, options and internal watcher together.
 */
export interface useFormFieldInstance {
    /**
     * The bindable props of the form field.
     */
    props: useFormFieldProps;
    /**
     * The live state of the form field.
     */
    states: useFormFieldState;
    /**
     * The options the field was registered with.
     */
    options?: useFormFieldOptions;
    /**
     * The internal pausable watcher tracking the field's value.
     */
    _watcher: {
        /**
         * Stops the watcher.
         */
        stop: () => void;
        /**
         * Pauses the watcher.
         */
        pause: () => void;
        /**
         * Resumes the watcher.
         */
        resume: () => void;
    };
}

/**
 * The object returned by `useForm`.
 */
export interface useFormReturn<T extends Record<string, any> = Record<string, any>> {
    /**
     * Defines a form field and returns its state and bindable props.
     * @param field - The name of the form field to define.
     * @param options - Configuration options for the field, such as validation rules.
     * @returns The field's state and bindable props.
     */
    defineField: (field: string, options?: useFormFieldOptions) => { state: useFormFieldState; props: useFormFieldProps };
    /**
     * Set the value of a form field.
     * @param field - The name of the form field.
     * @param value - The new value of the form field.
     */
    setFieldValue: (field: string, value: any) => void;
    /**
     * Get the state of a form field.
     * @param field - The name of the form field.
     * @returns The state of the form field, or `undefined` if the field is not registered.
     */
    getFieldState: (field: string) => useFormFieldState | undefined;
    /**
     * Handles the form submission, running validation before invoking the given callback.
     * @param event - The submit event.
     */
    handleSubmit: (event: any) => any;
    /**
     * Handles the form reset, resetting the form state before invoking the given callback.
     * @param event - The reset event.
     */
    handleReset: (event: any) => any;
    /**
     * Validates the form or a specific field.
     * @param field - The name of the form field to validate.
     */
    validate: (field: string) => any;
    /**
     * Sets the values of the form fields.
     * @param values - The values to set.
     */
    setValues: (values: Partial<T>) => void;
    /**
     * Resets the entire form state, clearing values and validation statuses.
     */
    reset: () => void;
    /**
     * Whether the form is valid.
     */
    valid: boolean;
    /**
     * The state of each registered form field, with the field name as the key and its state as the value.
     */
    states: Record<string, useFormFieldState>;
    /**
     * The registered fields of the form, keyed by field name.
     */
    fields: Record<string, useFormFieldInstance>;
}

/**
 * Resolver options passed to the form-level resolver function.
 */
export interface useFormResolverOptions<T extends Record<string, any> = Record<string, any>> {
    /**
     * The values of the form fields.
     */
    values: T;
    /**
     * The names of the form fields.
     */
    names: string[] | undefined;
}

/**
 * Configuration options for `useForm`.
 */
export interface useFormOptions<T extends Record<string, any> = Record<string, any>> {
    /**
     * A function that resolves validation logic.
     * @param {useFormResolverOptions} e - Resolver options
     */
    resolver?: (e: useFormResolverOptions<T>) => Promise<Record<string, any>> | Record<string, any> | undefined;
    /**
     * The initial values for the form fields.
     */
    initialValues?: T | undefined;
    /**
     * Whether to validate the form fields when the values change.
     * @defaultValue true
     */
    validateOnValueUpdate?: boolean | string[];
    /**
     * Whether to validate the form fields when they lose focus (on blur).
     * @defaultValue false
     */
    validateOnBlur?: boolean | string[];
    /**
     * Whether to validate the form fields immediately after the form is mounted.
     * @defaultValue false
     */
    validateOnMount?: boolean | string[];
    /**
     * Whether to validate the form fields when the form is submitted.
     * @defaultValue true
     */
    validateOnSubmit?: boolean | string[];
}

/**
 * useForm is a composable that provides form state management and validation.
 * @param {useFormOptions} options - Form options.
 * @returns {useFormReturn} An object exposing the form's state and methods.
 */
export declare function useForm<T extends Record<string, any> = Record<string, any>>(options?: useFormOptions<T>): useFormReturn<T>;
